fn numpy_where(condition: Vec<bool>, x: Vec<f32>, y: Vec<f32>) -> Vec<f32> {
    // All three vectors must have the same length
    assert_eq!(
        condition.len(),
        x.len(),
        "condition and x must have the same length"
    );
    assert_eq!(
        condition.len(),
        y.len(),
        "condition and y must have the same length"
    );

    // Build the result by zipping the three inputs together.
    // For each index i, pick x[i] if condition[i] is true, else pick y[i].
    condition
        .into_iter()
        .zip(x.into_iter().zip(y.into_iter()))
        .map(|(cond, (xi, yi))| if cond { xi } else { yi })
        .collect()
}

